$("capture-start").addEventListener("click", () => guarded("capture", async () => { try { const result = await api("/api/captures/start", { method: "POST" }); renderCaptureStatus(result); notice("Packet capture started", true); } catch (error) { notice(error.message); } })); $("capture-stop").addEventListener("click", () => guarded("capture", async () => { try { const result = await api("/api/captures/stop", { method: "POST" }); renderCaptureStatus(result); notice("Capture stopped and saved", true); } catch (error) { notice(error.message); } }));
