function generatedPassword() { const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789"; if (!globalThis.crypto?.getRandomValues) return "PinePi-Choose-A-New-Password"; const values = new Uint8Array(16); crypto.getRandomValues(values); return `PinePi-${Array.from(values, value => alphabet[value % alphabet.length]).join("")}`; }
async function copyText(value, input) { if (!value) throw new Error("Nothing to copy"); try { if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(value); return true; } } catch {} input.focus(); input.select(); input.setSelectionRange(0, input.value.length); let copied = false; try { copied = document.execCommand("copy"); } catch { copied = false; } if (!copied) { const fallback = element("textarea"); fallback.value = value; fallback.setAttribute("readonly", ""); fallback.style.position = "fixed"; fallback.style.opacity = "0"; document.body.append(fallback); fallback.select(); try { copied = document.execCommand("copy"); } finally { fallback.remove(); } } if (!copied) throw new Error("Copy failed; select the visible password and copy it manually"); return true; }
$("copy-lab-password").addEventListener("click", async () => { const button = $("copy-lab-password"); try { await copyText($("lab-password").value, $("lab-password")); button.textContent = "Copied ✓"; notice("Lab AP password copied", true); setTimeout(() => { button.textContent = "Copy Password"; }, 1800); } catch (error) { notice(error.message); } });
