function renderTrainingStatus(status) { setBadge("lab-state", status.running ? "Running" : "Stopped", status.running ? "good" : ""); setText("lab-interface", status.interface); setText("lab-gateway", status.gateway); setText("lab-forwarding", status.forwarding ? `Enabled via ${status.uplink || "uplink"}` : "Disabled"); setText("lab-client-count", status.client_count || 0, "0"); setText("lab-error", status.last_error || "No errors."); const clients = (status.clients || []).map(client => listRow(client.mac, `${client.signal ?? "Unknown"} dBm · RX ${bytes(client.rx_bytes)} · TX ${bytes(client.tx_bytes)}`)); replace($("lab-clients"), ...(clients.length ? clients : [element("div", "empty-state", "No connected clients.")])); $("lab-stop").disabled = !status.running; }
async function refreshTraining() { const status = await api("/api/training-ap/status"); renderTrainingStatus(status); if (status.selected_target && !state.selected) state.selected = status.selected_target; renderCloneSource(); if (status.running) { try { const credentials = await api("/api/training-ap/credentials"); $("lab-ssid").value = credentials.ssid; $("lab-password").value = credentials.password; $("lab-channel").value = credentials.channel; } catch (error) { setText("lab-error", `${error.message}. Connect through the Management network to view the Lab password.`); } } else { if (!$("lab-ssid").value) $("lab-ssid").value = state.selected?.ssid || "PinePi-Lab"; if (!$("lab-password").value) $("lab-password").value = generatedPassword(); } }
$("lab-form").addEventListener("submit", event => { event.preventDefault(); guarded("training", async () => { try { const body = { ssid: $("lab-ssid").value, password: $("lab-password").value, channel: Number($("lab-channel").value) }; await api("/api/training-ap/start", { method: "POST", body: JSON.stringify(body) }); notice("PinePi Lab AP started", true); await refreshTraining(); } catch (error) { notice(error.message); } }); });
