function activePayload() { if (!state.selected) throw new Error("Select an access point in Recon first"); if (!$("active-authorized").checked) throw new Error("Authorization acknowledgement is required"); return { ssid: state.selected.ssid || "", bssid: state.selected.bssid, channel: Number(state.selected.channel), authorized: true }; }
function confirmActiveTest(type, payload) { return confirm(`ACTIVE WIRELESS TEST\n\nType: ${type}\nTarget SSID: ${payload.ssid || "Hidden"}\nTarget BSSID: ${payload.bssid}\nClient: ${payload.client || "Entire selected BSSID"}\nChannel: ${payload.channel}\n\nConnected devices may temporarily lose connectivity. Continue?`); }
function renderActiveStatus(active) { state.active = active; setText("active-type", active.running ? active.type : "No active test"); fillDetails($("active-details"), [["Status", active.running ? "Running" : active.stop_reason || "Stopped"], ["Target", active.target?.bssid || active.bssid || "None"], ["Client", active.target?.client || active.client || "Entire BSSID"], ["Channel", active.target?.channel || active.channel || "—"], ["Adapter", active.interface || "—"], ["Elapsed", duration(active.elapsed_seconds)], ["Runtime limit", active.runtime_seconds ? `${active.runtime_seconds}s` : "—"]]); $("active-output").textContent = active.recent_output || (active.simulated ? "SIMULATED active-test state" : "No active output."); $("stop-active").disabled = !active.running; $("start-deauth").disabled = Boolean(active.running || state.live?.running || state.capture?.running); $("start-mdk4").disabled = $("start-deauth").disabled; }
