$("monitor-enable").addEventListener("click", () => guarded("monitor", async () => { try { const channel = state.selected?.channel || null; await api("/api/wireless-tools/monitor/enable", { method: "POST", body: JSON.stringify({ channel }) }); notice("Monitor mode enabled", true); await refreshWirelessTools(); } catch (error) { notice(error.message); } }));
$("monitor-disable").addEventListener("click", () => guarded("monitor", async () => { try { await api("/api/wireless-tools/monitor/disable", { method: "POST" }); notice("Adapter restored to managed mode", true); await refreshWirelessTools(); } catch (error) { notice(error.message); } }));
$("monitor-conflicts").addEventListener("click", () => guarded("monitor-conflicts", async () => { try { const result = await api("/api/wireless-tools/monitor/conflicts"); $("monitor-conflict-output").textContent = result.lines?.length ? result.lines.join("\n") : "No conflicting processes reported."; notice(result.note, !result.conflicts_detected); } catch (error) { $("monitor-conflict-output").textContent = error.message; notice(error.message); } }));
