$("stop-active").addEventListener("click", () => guarded("active", async () => { try { const result = await api("/api/wireless-tools/active/stop", { method: "POST" }); renderActiveStatus(result); notice("Active test stopped", true); } catch (error) { notice(error.message); } }));

async function refreshSecurityAnalysis() { const kismet = await api("/api/security-analysis/kismet/status"); setBadge("kismet-state", kismet.available ? "Available" : "Missing", kismet.available ? "good" : "warning"); fillDetails($("kismet-details"), [["Version", kismet.version || "Not installed"], ["Engine", kismet.engine_selection], ["API configured", kismet.api_available ? "Yes" : "No"], ["Status", kismet.explanation]]); if (!state.sessionId) { replace($("rogue-results"), element("div", "empty-state", "Open a Recon session and create trusted profiles to calculate anomalies.")); return; } const result = await api(`/api/security-analysis/rogue-access-points?session_id=${encodeURIComponent(state.sessionId)}`); const rows = result.items.map(item => { const reasons = item.reasons.map(reason => reason.message).join(" "); return listRow(`${item.risk} · ${item.ssid || "Hidden"}`, `${item.bssid} · score ${item.score}/100 · ${reasons}`, element("span", `badge ${item.risk === "HIGH" ? "bad" : "warning"}`, item.classification)); }); replace($("rogue-results"), ...(rows.length ? rows : [element("div", "empty-state", "No trusted-profile anomalies in this session.")])); }
$("refresh-security").addEventListener("click", () => refreshSecurityAnalysis().catch(error => notice(error.message)));
