function setExpertMode(value) { document.body.classList.toggle("expert", value); $("expert-mode").checked = value; try { localStorage.setItem("pinepi-ui-mode", value ? "expert" : "guided"); } catch {} if (state.page === "recon" && state.objectTab === "aps") loadAccessPoints().catch(() => {}); }
