$("run-audit").addEventListener("click", async () => { try { const result = await api("/api/audit"); const heading = element("h3", "", `${result.rating} · ${result.score}/100`), list = element("ul"); result.findings.forEach(finding => list.append(element("li", "", finding))); replace($("audit-results"), heading, list); } catch (error) { notice(error.message); } });
$("generate-report").addEventListener("click", () => guarded("report", async () => { if (!state.sessionId) { notice("Open a Recon session first"); return; } $("report-output").textContent = "Generating bounded session summary…"; try { const result = await api(`/api/reports/recon/${encodeURIComponent(state.sessionId)}`); $("report-output").textContent = JSON.stringify(result, null, 2); } catch (error) { $("report-output").textContent = error.message; notice(error.message); } }));

document.querySelectorAll("[data-refresh]").forEach(button => button.addEventListener("click", () => refreshPage(true).catch(error => notice(error.message))));
async function refreshPage(forceTop = false) { await refreshTopbar(forceTop); switch (state.page) { case "dashboard": await refreshDashboard(); break; case "recon": await refreshRecon(); break; case "access-point": await refreshTraining(); break; case "campaigns": await refreshAudit(); break; case "logging": await refreshLogs(); break; case "modules": await refreshModules(); break; case "captures": await loadCaptureLibrary(); break; case "wireless-tools": await refreshWirelessTools(); break; case "security-analysis": await refreshSecurityAnalysis(); break; case "packet-capture": await refreshPacketCapture(); break; case "diagnostics": await refreshDiagnostics(); break; case "settings": await refreshSettings(); break; default: break; } }
function schedulePoll() { const slowPages = new Set(["logging", "modules", "reports", "settings"]); clearTimeout(state.timer); state.timer = setTimeout(poll, slowPages.has(state.page) ? 15000 : state.pollDelay); }
async function poll() { clearTimeout(state.timer); try { await guarded("page-refresh", refreshPage); } catch (error) { notice(error.message); } schedulePoll(); }

renderCloneSource(); if (!$("lab-password").value) $("lab-password").value = generatedPassword(); poll();
